    public void updateFromVendLines()
    {
        this.MetVariance    = this.ImportedAmount - this.totalLineAmount();
        this.MetVarInTol    = this.MetVariance <= VendParameters::find().ExtendedPriceToleranceAmount;
        this.MetClaimExist  = this.hasClaimLines();
        this.MetGSTVariance = this.ImportedSalesTax - this.totalLineTaxAmount();

        next updateFromVendLines();
    }

    public Amount totalLineTaxAmount()
    {
        PurchTotals purchTotals;

        purchTotals = PurchTotals::newParmTable(this, PurchUpdate::All, this.ParmId, '', this.Ordering);

        purchTotals.calc();

        return purchTotals.purchTaxTotal();
    }

    public boolean hasClaimLines()
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;

        select count(RecId) from vendInvoiceInfoLine
            where
                vendInvoiceInfoLine.ParmId          == this.ParmId &&
                vendInvoiceInfoLine.TableRefId      == this.TableRefId &&
                vendInvoiceInfoLine.MetClaimLine    == NoYes::Yes;

        return vendInvoiceInfoLine.RecId > 0;
    }

    /// <summary>
    /// Retrieves the sum of the <c>LineAmount</c> fields for all invoice lines.
    /// </summary>
    /// <returns>
    /// The sum of the <c>LineAmount</c> fields for all invoice lines.
    /// </returns>
    public Amount totalLineAmount()
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;
        Amount              total;

        while select vendInvoiceInfoLine
            where
                vendInvoiceInfoLine.ParmId == this.ParmId &&
                vendInvoiceInfoLine.TableRefId == this.TableRefId
        {
            total += CurrencyExchangeHelper::amount(vendInvoiceInfoLine.LineAmount, vendInvoiceInfoLine.CurrencyCode);
        }

        return total;
    }
